#!/usr/bin/env python3
"""Генератор index.html — копии DISC-теста Stratoplan (без бэкенда, офлайн).
Читает эталонный questions.json и выдает jedan самодостаточный файл."""
import json, os

HERE = os.path.dirname(os.path.abspath(__file__))
REF = os.path.join(HERE, "disc", "test-assignment", "reference", "questions.json")

with open(REF, encoding="utf-8") as f:
    data = json.load(f)

questions = data["questions"]

# JSON для встраивания в JS
QUESTIONS_JSON = json.dumps(questions, ensure_ascii=False, separators=(",", ":"))

html = f"""<!DOCTYPE html>
<html lang="ru">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
<title>Бесплатный тест DISC для руководителей</title>
<style>
:root {{
  --bg: #0f172a;
  --bg2: #111c38;
  --card: #ffffff;
  --ink: #0f172a;
  --muted: #64748b;
  --line: #e2e8f0;
  --accent: #4f6ef7;
  --accent-dk: #3f58cf;
  --d: #ef4444;
  --i: #f59e0b;
  --s: #22c55e;
  --c: #3b82f6;
  --shadow: 0 10px 40px rgba(2, 6, 23, .35);
  --radius: 16px;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
}}
* {{ box-sizing: border-box; }}
html, body {{ margin: 0; padding: 0; }}
body {{
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background: linear-gradient(160deg, var(--bg) 0%, var(--bg2) 60%, #0b1226 100%);
  color: var(--ink);
  min-height: 100vh;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  padding-bottom: 60px;
  scrollbar-width: thin;
}}
.wrap {{ max-width: 920px; margin: 0 auto; padding: 0 20px; }}

/* ---------- Landing ---------- */
.hero {{ text-align: center; padding: 56px 0 28px; }}
.eyebrow {{
  display: inline-block; font-size: 13px; font-weight: 600; letter-spacing: .08em;
  text-transform: uppercase; color: #a9b8ff; background: rgba(79,108,247,.14);
  border: 1px solid rgba(79,108,247,.35); padding: 6px 14px; border-radius: 999px; margin-bottom: 22px;
}}
h1 {{
  font-size: clamp(28px, 5vw, 46px); line-height: 1.1; margin: 0 0 16px;
  color: #fff; font-weight: 800; letter-spacing: -.02em;
}}
.hero p.lede {{ font-size: clamp(15px, 2.2vw, 19px); color: #c3ccf2; max-width: 620px; margin: 0 auto 32px; }}
.btn {{
  display: inline-flex; align-items: center; justify-content: center; gap: 10px;
  font-family: inherit; font-size: 17px; font-weight: 700; cursor: pointer;
  border: none; border-radius: 12px; padding: 15px 34px; transition: transform .08s ease, box-shadow .2s ease, background .2s;
}}
.btn--primary {{ background: linear-gradient(180deg, #5b79fa, var(--accent)); color: #fff; box-shadow: 0 10px 24px rgba(79,108,247,.42); }}
.btn--primary:hover {{ transform: translateY(-1px); box-shadow: 0 14px 30px rgba(79,108,247,.52); }}
.btn--primary:active {{ transform: translateY(1px); }}
.features {{ display: flex; justify-content: center; flex-wrap: wrap; gap: 14px; margin-top: 40px; }}
.feature {{
  background: rgba(255,255,255,.05); border: 1px solid rgba(255,255,255,.10); color: #d6ddf6;
  padding: 14px 18px; border-radius: 12px; font-size: 14px; display: flex; align-items: center; gap: 10px; min-width: 190px;
}}
.feature b {{ color: #fff; font-weight: 700; }}
.icon {{ flex: 0 0 auto; }}

/* ---------- Modal ---------- */
.modal-overlay {{
  position: fixed; inset: 0; background: rgba(6, 10, 24, .72); backdrop-filter: blur(3px);
  display: none; align-items: flex-start; justify-content: center; z-index: 100; padding: 32px 16px; overflow-y: auto;
}}
.modal-overlay.open {{ display: flex; }}
.modal {{
  background: var(--card); border-radius: 22px; width: 100%; max-width: 900px;
  box-shadow: var(--shadow); overflow: hidden; margin: auto;
}}
.modal__head {{ padding: 26px 30px 20px; border-bottom: 1px solid var(--line); }}
.modal__title {{ font-size: 24px; font-weight: 800; margin: 0 0 6px; color: var(--ink); }}
.modal__sub {{ font-size: 14px; color: var(--muted); margin: 0 0 8px; font-style: italic; }}
.modal__lead {{ font-size: 15px; color: #334155; }}
.modal__body {{ padding: 22px 30px 28px; }}

/* tabs */
.tabs {{ display: flex; gap: 8px; margin-bottom: 22px; overflow-x: auto; padding-bottom: 4px; scrollbar-width: thin; }}
.tab {{
  flex: 0 0 auto; border: 1px solid var(--line); background: #fff; color: #475569;
  border-radius: 999px; padding: 8px 16px; font-size: 14px; font-weight: 600; cursor: pointer;
  transition: background .15s, color .15s, border-color .15s;
}}
.tab:hover {{ border-color: #cbd5e1; }}
.tab.is-active {{ background: var(--accent); color: #fff; border-color: var(--accent); }}

/* grid */
.grid3 {{ display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }}
@media (max-width: 680px) {{ .grid3 {{ grid-template-columns: 1fr; }} }}
.pane {{ display: none; }}
.pane.is-active {{ display: block; animation: fade .25s ease; }}
@keyframes fade {{ from {{ opacity: 0; transform: translateY(6px); }} to {{ opacity: 1; transform: none; }} }}

/* card / list */
.card {{
  background: #fff; border: 1px solid var(--line); border-radius: 14px; padding: 14px 12px 12px;
  display: flex; flex-direction: column;
}}
.card__title {{ font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: .05em; color: var(--accent-dk); text-align: center; margin-bottom: 10px; }}
.card__foot {{ font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: .05em; color: var(--muted); text-align: center; margin-top: 10px; }}
.list {{ list-style: none; margin: 0; padding: 4px; min-height: 44px; border-radius: 10px; }}
.list.is-dragging {{ background: #f8fafc; }}
.item {{
  display: flex; align-items: center; gap: 10px; background: #f8fafc;
  border: 1px solid var(--line); border-radius: 10px; padding: 9px 10px 9px 14px; margin: 6px 0;
  font-size: 15px; color: #1e293b; cursor: grab; user-select: none; transition: box-shadow .12s, border-color .12s, transform .12s;
}}
.item:first-child {{ border-color: #b9c3fa; box-shadow: 0 0 0 1px rgba(79,108,247,.25) inset; }}
.item:last-child {{ border-color: #cbd5e1; }}
.item.is-dragging {{ opacity: .5; }}
.item.is-over {{ border-color: var(--accent); }}
.grip {{ flex: 0 0 auto; opacity: .5; }}
.item-text {{ flex: 1 1 auto; line-height: 1.25; }}
.type-tag {{
  flex: 0 0 auto; font-size: 11px; font-weight: 700; text-transform: uppercase; border-radius: 6px;
  padding: 2px 7px; letter-spacing: .04em; color: #fff; opacity: 0; transition: opacity .15s;
}}
.item:hover .type-tag, .list:hover .item .type-tag {{ opacity: .92; }}
.type-tag.t-d {{ background: var(--d); }}
.type-tag.t-i {{ background: var(--i); }}
.type-tag.t-s {{ background: var(--s); }}
.type-tag.t-c {{ background: var(--c); }}

/* progress */
.progress {{ margin: 24px 0 6px; height: 7px; background: #e2e8f0; border-radius: 999px; overflow: hidden; }}
.progress__bar {{ height: 100%; background: linear-gradient(90deg, var(--accent), #7c93fb); width: 12.5%; transition: width .3s ease; }}

/* actions */
.actions {{ display: flex; justify-content: space-between; align-items: center; margin-top: 18px; gap: 12px; }}
.nav {{ position: relative; }}
.btn--ghost {{ background: #fff; color: #334155; border: 1px solid #cbd5e1; padding: 11px 22px; border-radius: 10px; font-size: 15px; font-weight: 650; cursor: pointer; transition: background .15s, border-color .15s; }}
.btn--ghost:hover {{ background: #f1f5f9; border-color: #b6c0d5; }}
.btn--primary-sm {{ background: linear-gradient(180deg, #5b79fa, var(--accent)); color: #fff; padding: 11px 26px; border-radius: 10px; font-size: 15px; font-weight: 650; border: none; cursor: pointer; box-shadow: 0 6px 16px rgba(79,108,247,.35); transition: transform .08s; }}
.btn--primary-sm:hover {{ transform: translateY(-1px); }}
.btn--primary-sm:active {{ transform: translateY(0); }}
.btn:disabled {{ opacity: .45; cursor: not-allowed; transform: none !important; box-shadow: none !important; }}
.progress-label {{ font-size: 13px; color: var(--muted); font-weight: 600; }}

/* ---------- Results ---------- */
.results {{ padding: 40px 0 20px; }}
.results h2 {{ color: #fff; font-size: clamp(24px, 4vw, 34px); text-align: center; margin-bottom: 4px; font-weight: 800(); }}
.results .sub {{ text-align: center; color: #c3ccf2; text-align: center; margin-bottom: 30px; }}
.scoreboard {{ display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; margin-bottom: 32px; }}
@media (max-width: 600px) {{ .scoreboard {{ grid-template-columns: repeat(2, 1fr); }} }}
.bank {{ background: rgba(255,255,255,.06); border: 1px solid rgba(255,255,255,.12); border-radius: 14px; padding: 18px; text-align: center; }}
.bank__flag {{ font-weight: 800; font-size: 34px; margin-bottom: 2px; }}
.bank__name {{ font-size: 13px; color: #c3ccf2; letter-spacing: .05em; text-transform: uppercase; margin-bottom: 10px; }}
.bank__bar {{ height: 9px; background: rgba(255,255,255,.13); border-radius: 999px; overflow: hidden; margin-bottom: 8px; }}
.bank__barinner {{ height: 100%; border-radius: 999px; transition: width .8s cubic-bezier(.2,.8,.2,1); }}
.bank__val {{ font-size: 15px; font-weight: 700; color: #fff; }}
.bank.d .bank__flag, .bank.d .bank__barinner {{ color: var(--d); }}
.bank.d .bank__barinner {{ background: var(--d); }}
.bank.i .bank__flag, .bank.i .bank__barinner {{ color: var(--i); }}
.bank.i .bank__barinner {{ background: var(--i); }}
.bank.s .bank__flag, .bank.s .bank__barinner {{ color: var(--s); }}
.bank.s .bank__barinner {{ background: var(--s); }}
.bank.c .bank__flag, .bank.c .bank__barinner {{ color: var(--c); }}
.bank.c .bank__barinner {{ background: var(--c); }}

.summary {{ background: rgba(255,255,255,.06); border: 1px solid rgba(255,255,255,.12); border-radius: 16px; padding: 26px 28px; color: #e7ecff; }}
.summary h3 {{ margin-top: 0; color: #fff; font-size: 20px; }}
.summary dl {{ display: grid; grid-template-columns: auto 1fr; gap: 10px 18px; margin: 8px 0 0; }}
.summary dt {{ font-weight: 700; color: #fff; }}
.summary dt .tt {{ margin-left: 8px; font-size: 11px; padding: 1px 6px; border-radius: 5px; vertical-align: middle; }}
.summary dd {{ margin: 0; color: #c3ccf2; font-size: 14px; }}
@media (max-width: 520px) {{ .summary dl {{ grid-template-columns: 1fr; gap: 6px; }} }}
.share {{ margin-top: 24px; display: flex; flex-wrap: wrap; gap: 12px; align-items: center; }}
.share input {{ flex: 1 1 280px; min-width: 0; padding: 11px 14px; border-radius: 10px; border: 1px solid #cbd5e1; font-size: 14px; font-family: inherit; }}
.share .btn-share {{ background: #fff; color: #0f172a; padding: 11px 20px; border-radius: 10px; font-weight: 650; border: none; cursor: pointer; }}
.disclaimer {{ margin-top: 26px; padding: 16px 18px; background: rgba(245,158,11,.10); border: 1px solid rgba(245,158,11,.35); border-radius: 12px; color: #f3d9a8; font-size: 14px; }}
