            </ul>
            <div class="disc-card__foot">Я наименее</div>
          </div>'''.format(id=q["id"], items=tags)
    ).format(grip=GRIP)

CARDS = """
        <div class="disc-grid">""" + "".join(
    CARD_HTML
    for q in []  # placeholder for clarity
) + "</div>"

STEP_PANES = ""
for s in range(8):
