#!/usr/bin/env python3
"""Генератор index.html — копии DISC-теста Stratoplan (без бэкенда/сети).
Читает эталонный questions.json и выдает один самодостаточный offline-файл."""
import json
import os

HERE = os.path.dirname(os.path.abspath(__file__))
REF = os.path.join(HERE, "disc", "test-assignment", "reference", "questions.json")
OUT = os.path.join(HERE, "index.html")

with open(REF, encoding="utf-8") as f:
    data = json.load(f)
questions = data["questions"]

groups = [[q for q in questions if q["step"] == s] for s in range(8)]
assert all(len(g) == 3 for g in groups)

QUESTIONS_JSON = json.dumps(questions, ensure_ascii=False, separators=(",", ":"))

RU_STEP = [
    "В первый", "В второй", "В третий", "В четвертый",
    "В пятый", "В шестой", "В седьмой", "В восьмой",
]
TYPE_NAME = {
    "d": "Доминирующий · высокая инициатива",
    "i": "Влияющий · ориентация на людей",
    "s": "Поддерживающий · стабильность и надёжность",
    "c": "Сознательный · внимание к деталям",
}
TYPE_LABEL = {"d": "D", "i": "I", "s": "S", "c": "C"}


def esc(s):
    return (s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;"))


GRIP_SVG = (
    '<svg class="grip" aria-hidden="true" width="15" height="15" viewBox="0 0 16 16"'
    ' fill="currentColor"><circle cx="6" cy="4" r="1.5"/><circle cx="10" cy="4" r="1.5"/>'
    '<circle cx="6" cy="8" r="1.5"/><circle cx="10" cy="8" r="1.5"/>'
    '<circle cx="6" cy="12" r="1.5"/><circle cx="10" cy="12" r="1.5"/></svg>'
)

BRIEF = {
    "d": ("Характеристика D (Доминирующий)",
          "Ваш доминирующий стиль руководства близок к прямому, решительному лидеру. Вы быстро принимаете решения, ставите цели и добиваетесь результатов, ориентируясь на эффект. Вам не чужды прямота и напор — в приоритете результат и движение вперёд."),
    "i": ("Характеристика I (Влиющий)",
          "Ваш влиющий стиль выражается в общительности и оптимизме. Вы легко находите контакт с людьми, вдохновляете и мотивируете команду, энергично презентуете идеи. Ваша сила — коммуникация, доверие и позитивная атмосфера вокруг себя."),
    "s": ("Характеристика S (Поддерживающий)",
          "Ваш поддержывающий стиль руководства строится на терпении и надёжности. Вы надёжный командный игрок, умеете слушать и поддерживать других, цените стабильность и ясные процессы. Вас ценят за спокойствие и искреннюю заботу о коллегах."),
    "c": ("Характеристика C (Сознательный)",
          "ВАш сознательный стиль руководства отличается вниманием к качеству и деталям. Вы стремитсяесь к точности, анализируете и следуете стандартам. Ваша сила — системность, аккуратность и взвешанные аргументы."),
}


def card_html(q):
    items = []
    for it in q["items"]:
        type_label = TYPE_LABEL.get(it["type"], "?")
        items.append(
            '''          <li class="disc-item">
            <span class="grip" aria-hidden="true">{grip}</span>
            <span class="disc-item__text">{text}</span>
            <span class="disc-item tag t-{t}" data-type="{t}" aria-hidden="true">{type_label}</span>
          </li>'''.format(
                grip=GRIP_SVG,
                text=esc(it["text"]),
                t=it["type"],
                type_label=type_label,
            )
        )
    items_html = "\n".join(items)
    return '''
          <div class="disc-card">
            <div class="disc-card__title">Я наиболее</div>
            <ul class="disc-list" id="draggable-list{id}">
{items}
            </ul>
            <div class="disc-card__foot">Я наименее</div>
          </div>'''.format(id=q["id"], items=items_html)


PANES = ""
for s in range(8):
    cards = "".join(card_html(q) for q in groups[s])
    PANES += '''
      <div class="disc-pane" data-pane="{s}" role="tabpanel">
        {cards}
      </div>'''.format(s=s, cards=cards)

TABS = ""
for i in range(8):
    sel = "true" if i == 0 else "false"
    act = "is-active " if i == 0 else ""
    TABS += '''          <button class="{cls}" data-step="{i}" role="tab" aria-selected="{sel}">{label}</button>'''.format(
        cls=act, i=i, sel=sel, label= RU_STEP[i]
    )

