#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Генератор index.html — копия DISC-теста Stratoplan (single-file, offline)."
"Данные (24 вопроса + data-type) из эталонного questions.json."
"""
import json
import os

HERE = os.path.dirname(os.path.abspath(__file__))
REF = os.path.join(HERE, "disc", "test-assignment", "reference", "questions.json")
OUT = os.path.join(HERE, "index.html")

with open(REF, encoding="utf-8") as f:
    QUESTIONS = json.load(f)["questions"]
assert len(QUESTIONS) == 24, "need 24 questions, got %d" % len(QUESTIONS)

U = {}  # unicode placeholder markers -> replacement for JSON-safe embedding


def esc(s):
    return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&#62;").replace('"', "quot;")


def grip_svg():
    return ('<svg class="grip" aria-hidden="true" viewBox="0 0 16 16" width="16" height="16"'
            ' fill="currentColor"><circle cx="6" cy="3.5" r="1.4"/><circle cx="10" cy="3.5" r="1.4"/>'
            '<circle cx="6" cy="8" r="1.4"/><circle cx="10" cy="8" r="1.4"/><circle cx="6" cy="12.5" r="1.4"/>'
            '<circle cx="10" cy="12.5" r="1.4"/></svg>')


TAB_LABELS = ["В первый", "В второй", "В третий", "В четвертый",
              "В пятый", "В шестой", "В седьмой", "Восьмой"]


def items_to_json():
    items = [[it["text"], it["type"]] for it in QUESTIONS]
    return json.dumps(items, ensure_ascii=False, separators=(",", ":"))


TAB_BUTTONS = "".join(
    '<button class="disc-tab {act}" data-step="{n}" role="tab" aria-selected="{sel}" aria-controls="pane{n}">{lab}</button>'
    .format(act="is-active" if n == 0 else "", n=n, sel=("true" if n == 0 else "false"),
            lab=TAB_LABELS[n]) for n in range(8)
)

PANES = ""
for step in range(8):
    step_qs = [q for q in QUESTIONS if q["step"] == step]
    cards = ""
    for q in step_qs:
        lis = ""
        for it in q["items"]:
            lis += ('<li class="disc-item" data-type="{t}">'
                    '{grip}<span class="disc-item__text">{txt}</span>'
                    '<span class="disc-item tag t-{t}" data-type="{t}" aria-hidden="true">{tup}</span></li>'
                    ).format(t=it["type"], grip=grip_svg(), txt=esc(it["text"]),
                            tup=it["type"].upper())
        cards += ('<div class="disc-card"><div class="disc-card__title">Я наиболее</div>'
                  '<ul class="disc-list" id="list{id}">{lis}</ul>'
                  '<div class="disc-card__foot">Я наименее</div></div>'
                  ).format(id=q["id"], lis=lis)
    PANES += ('<div class="disc-pane{act}" data-pane="{step}" role="tabpanel" id="pane{step}">'
              '<div class="disc-grid3">{cards}</div></div>').format(
        step=step, cards=cards, act="is-active" if step == 0 else "")


