TOTAL_STEP = 8
STEP_LABELS = ["Шаг 1", "Шаг 2", "Шаг 3", "Шаг 4",
               "Шаг 5", "Шаг 6", "Шаг 7", "Шаг 8"]
STEP_TITLES = ["В первый", "Во второй", "В третий", "В четвёртый",
               "В пятый", "В шестой", "В седьмой", "Восьмой"]


def esc(s):
    return (s.replace("&", "&amp;").replace("<", "&lt;")
            .replace(">", "&gt;").replace('"', "&quot;"))


def make_items(items):
    out = []
    for it in items:
        out.append('<li class="disc-item" data-type="%s"><span class="disc-item__text">%s</span>'
                   '<span class="disc-item tag t-%s" data-type="%s" aria-hidden="true">%s</span></li>'
                   % (it["type"], esc(it["text"]), it["type"], it["type"], it["type"].upper()))
    return "".join(out)


def make_panes():
    parts = []
    for step in range(TOTAL_STEP):
        step_qs = [q for q in QUESTIONS if q["step"] == step]
        cards = []
        for q in step_qs:
            lis = make_items(q["items"])
            cards.append('<div class="disc-card"><div class="disc-card__title">'
                         'Я наиболее</div><ul class="disc-list" id="list%d">%s</ul>'
                         '<div class="disc-card__foot">Я наименее</div></div>' % (q["id"], lis))
        act = " is-active" if step == 0 else ""
        parts.append('<div class="disc-pane%s" data-pane="%d" role="tabpanel" id="pane%d">'
                     '<div class="disc-grid3">%s</div></div>' % (act, step, step, "".join(cards)))
    return parts


def make_tabs():
    out = []
    for n in range(TOTAL_STEP):
        act = " is-active" if n == 0 else ""
        sel = "true" if n == 0 else "false"
        out.append('<div class="disc-tab%s" data-step="%d" role="tab" aria-selected="%s" aria-controls="pane%d" aria-label="%s">%s</div>'
                   % (act, n, sel, n, STEP_LABELS[n], STEP_LABELS[n]))
    return "".join(out)


