JS = """\
;(function(){
  "use strict";
  var QUESTS = @@QUESTS__;
  var LABELS = @@LABELS__;
  var NAME_MAP = @@NAME_MAP__;
  var RES_MAP = @@RES_MAP__;
  var STEP = @@STEP__;
  var TOTAL=8, cur=0;
  var byId=function(id){return document.getElementById(id);};
  function renderTabs(){
    document.querySelectorAll(".disc-tab").forEach(function(t){var i=Number(t.dataset.step);var on=i===cur;t.classList.toggle("is-active",on);t.setAttribute("aria-selected",on?"true":"false");});
  }
  function renderPanes(){
    document.querySelectorAll(".disc-pane").forEach(function(p){p.classList.toggle("is-active", Number(p.dataset.pane)===cur);});
  }
  function render(){
    renderTabs(); renderPanes();
    byId("bar").style.width=((cur+1)/TOTAL*100)+"%";
    byId("label").textContent = STEP_LABELS[cur] + " · " + LABELS[cur];
  }
  function collect(){
    var arr=[];
    document.querySelectorAll(".disc-list").forEach(function(ul){
      var o=Array.prototype.slice.call(ul.children).map(function(li){return li.getAttribute("data-type");});
      arr.push(o);
    });
    return arr;
  }
  function score(){
    var arr=collect(); var maj=[],min=[];
    arr.forEach(function(ls){ if(ls[0])maj.push(ls[0]); if(ls[3])min.push(ls[3]); });
    var c=function(a,t){return a.filter(function(x){return x===t;}).length;};
    return {d:c(maj,"d")-c(min,"d"),i:c(maj,"i")-c(min,"i"),s:c(maj,"s")-c(min,"s"),c:c(maj,"c")-c(min,"c")};
  }
  function top(s){var a=["d","i","s","c"].map(function(t){return[t,s[t]];}).sort(function(x,y){return y[1]-x[1];});return a[0][0];}
  function showResults(){
    var s=score();
    ["d","i","s","c"].forEach(function(t){
      var val=s[t], w=Math.min(100,Math.abs(val)/24*100)/2;
      var b=document.getElementById("bbar_"+t);
      if(val>=0){ b.style.marginLeft="50%"; b.style.width=(w)+"%"; b.style.transform="none"; }
      else { b.style.marginLeft=(50-w)+"%"; b.style.width=(w)+"%"; }
      document.getElementById("val_"+t).textContent = (val>0?"+")+val;
    });
    var tt=top(s), r=RES_MAP[tt];
    byId("name0").textContent=NAME_MAP[tt]==undefined?tt:NAME_MAP[tt];
    byId("summary").innerHTML="<h3>"+r[0]+"</h3>"
      +"<dl><dt>Кратко</dt><dd>"+r[1]+"</dd>"
      +"<dt>Сильные стороны</dt><dd>"+r[2]+"</dd>"
      +"<dt>Слабые стороны</dt><dd>"+r[3]+"</dd>"
      +"<dt>Рекомендация</dt><dd>"+r[4]+"</dd></dl>";
    byId("inputLink").value=(location.origin||"")+location.pathname+"?type="+tt.toUpperCase();
  }
  var ov=byId("overlay");
  function open(){ov.classList.add("is-open");document.body.classList.add("no-scroll");render();}
  function close(){ov.classList.remove("is-open");byId("overlay").setAttribute("aria-hidden","true");document.body.classList.remove("no-scroll");render();}
  byId("startBtn").addEventListener("click",open);
  byId("discoveryBtn").addEventListener("click",open);
  byId("closeBtn").addEventListener("click",close);
  byId("closeBtn2").addEventListener("click",close);
  ov.addEventListener("click",function(e){if(e.target===ov)close();});
  byId("stepBackBtn").addEventListener("click",function(){if(cur>0){cur--;render();}});
  byId("stepNextBtn").addEventListener("click",function(){if(cur<TOTAL-1){cur++;render();}});
  byId("stepBack").addEventListener("click",function(){if(cur>0){cur--;render();}});
  byId("stepNext").addEventListener("click",function(){if(cur<TOTAL-1){cur++;render();}});
  byId("back").addEventListener("click",function(){if(cur>0){cur--;render();}});
  byId("next").addEventListener("click",function(){if(cur<TOTAL-1){cur++;render();}});
  byId("finish").addEventListener("click",function(){
    showResults();
    ov.classList.remove("is-open");
    document.body.classList.remove("no-scroll");
    byId("result").style.display="block";
    window.scrollTo(0,0);
  });
  byId("copyBtn").addEventListener("click",function(){
    var i=byId("inputLink"); i.select();
    try{document.execCommand("copy");}catch(e){}
    byId("copyBtn").textContent="Скопировано"; byId("copyBtn").classList.add("copied");
    setTimeout(function(){byId("copyBtn").textContent="Копировать ссылку";byId("copyBtn").classList.remove("copied");},1500);
  });
  byId("againBtn").addEventListener("click",function(){location.reload();});
  document.addEventListener("keydown",function(e){if(e.key==="Escape"&&ov.classList.contains("is-open"))close();});
  render();
})();
"""

