#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Generator for index.html — a single-file, offline DISC-test copy.
All question data is read from the reference questions.json so the wording
matches the original byte-for-byte (incl. the embedded Latin 'c' in Эkespressivny)."""
import json
import os

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)
REF = os.path.join(HERE, "..", "test-assignment", "reference", "questions.json")
OUT = os.path.join(ROOT, "index.html")

with open(REF, encoding="utf-8") as f:
    QUESTIONS = json.load(f)["questions"]
assert len(QUESTIONS) == 24, len(QUESTIONS)

TOTAL = 8
LABELS = ["Третий первый", "Четвёртый второй", "Третий", "Четвёртый",
          "Пятый", "Шестой", "Седьмой", "Восьмой"]
STEP_TITLES_STEPS = ["Первый", "Второй", "Третий", "Четвёртый",
                     "Пятый", "Шестой", "Седьмой", "Восьмой"]

TAB_TITLE = ["В первый", "Во второй", "В третий", "В четвёртый",
             "В пятый", "В шестой", "В седьмой", "Восьмой"]


def esc(s):
    return (s.replace("&", "&amp;").replace("<", "&lt;")
            .replace(">", "&gt;").replace('"', "&quot;"))


def items_html(items):
    out = []
    for it in items:
        out.append(
            '<li class="disc-item" data-type="%s"><span class="disc-item__text">%s'
            '</span><span class="disc-item tag t-%s" data-type="%s" aria-hidden="true">%s'
            '</span></li>' % (it["type"], esc(it["text"]), it["type"],
                             it["type"], it["type"].upper()))
    return (
        '<ul class="disc-list" id="list{id}">'
        + "".join(out)
        + "</ul>"
    )


def tab_buttons():
    parts = []
    for n, label in enumerate(TAB_TITLE):
        act = " is-active" if n == 0 else ""
        sel = "true" if n == 0 else "false"
        parts.append('<div class="disc-tab%s" data-step="%d" role="tab" aria-selected="%s" aria-controls="pane%d">%s</div>'
                     % (act, n, sel, n, esc(label)))
    return "".join(parts)


def panes():
    result = []
    for step in range(TOTAL):
        qs = [q for q in QUESTIONS if q["step"] == step]
        cards = ""
        for q in qs:
            cards += (
                '<div class="disc-card"><div class="disc-card__title">Я Наиболее</div>'
                + items_html(q["items"])
                + '<div class="disc-card__foot">Я Наименее</div></div>'
            )
        act = " is-active" if step == 0 else ""
        result.append(
            '<div class="disc-pane%s" data-pane="%d" role="tabpanel" id="pane%d">'
            '<div class="disc-grid3">%s</div></div>' % (act, step, step, cards))
    return "".join(result)


QUEST_JSON = json.dumps([[it["text"], it["type"]] for it in QUESTIONS], ensure_ascii=False,
                        separators=(",", ":"))
NAME_JSON = json.dumps({"d": "D · Доминирующий", "i": "I · Влияющий",
                        "s": "S · Поддерживающий", "c": "C · Сознательный"}, ensure_ascii=False,
                       separators=(",", ":"))
STEP_JSON = json.dumps(TAB_TITLE, ensure_ascii=False)
RES_MAP = {
    "d": ["D · Доминирующий",
          "Ты ставишь цели и добиваешься их — ты «движок» команды. Принимаешь быстрые решения, берёшь ответственность на себя, прямо говоришь и идёшь к результату.",
          "напор, решительность, ориентация на результат и прямые вызовы",
          "нетерпение, давление на людей, игнорирование деталей и эмоций",
          "Дай себе паузу перед важными решениями; обращай внимание не только на результат, но и на людей"],
    "i": ["I · Влияющий",
          "Ты — душа компании и вдохновитель. Находимый лёгкий контакт с людьми, заряжаешь позитивом, убеждаешь и мотивируете команду.",
          "общительность, оптимизм, харизма и навыки коммуникации",
          "рассеянность, поверхностность, сложность с рутиной",
          "Доверь рутины и документирование системе; сосредоточься на завершении начатого"],
    "s": ["S · Поддерживающий",
          "Ты надёжный, терпеливый и верный. Ценишь стабильность и искреннюю заботу о людях, отлично слушаешь и умеешь дать поддержку",
          "терпение, надёжность, вниматель слушатель, стабильность и постоянство",
          "нежелание перемен, неуверенность, сложность сказать «нет»",
          "Потихоньку бери инициативу; береги собственные личные границы"],
    "c": ["C · Сознательный",
          "Ты внимательный к деталям и качеству. Ценишь стандарты, точность и правила; принимаешь решения на основе фактов и анализа.",
          "системность, стремление к качеству, внимательность к деталям, аргументированность",
          "перфекционизм, нерешительность, критичность",
          "Создай разумные дедлайны; разреи себе «хорошо достаточно» для черновых решений"],
}
RES_JSON = json.dumps(RES_MAP, ensure_ascii=False, separators=(",", ":"))

JS = r"""
;(function () {
  "use strict";
  var QUESTS = @@QUESTS__;
  var STEP = @@STEP__;
  var NAME_MAP = @@NAME_MAP__;
  var RES_MAP = @@RES_MAP__;
  var TOTAL = 8;
  var cur = 0;

  function byId(id) { return document.getElementById(id); }
  function el(sel) { return document.querySelector(sel); }
  function es(s) { return (String(s) || "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;"); }

  var dragSrc = null;
  function clearOver() {
    Array.prototype.forEach.call(document.querySelectorAll(".disc-item.is-over"), function (x) { x.classList.remove("is-over"); });
  }
  function sortInsert(drag, ref, refY) {
    var ul = ref.parentElement || document;
    var list = ul.classList.contains("disc-list") ? ul : el(".disc-list");
    var items = Array.prototype.slice.call(list.children);
    var idx = items.indexOf(ref);
    if (!refY) { var r = ref.getBoundingClientRect(); refY = r.top + r.height / 2; }
    var down = refY > (list.getBoundingClientRect().top + refY);
    if (drag === ref) return;
    if (idx >= 0) { list.insertBefore(drag, (down && ref.nextElementSibling) || ref); }
  }
  document.addEventListener("dragstart", function (e) {
    var t = e.target;
    if (t.classList && t.classList.contains("disc-item")) { dragSrc = t; t.classList.add("is-dragging"); e.dataTransfer.effectAllowed = "move"; }
  }, false);
  document.addEventListener("dragend", function () {
    if (dragSrc) dragSrc.classList.remove("is-dragging"); dragSrc = null; clearOver();
  }, false);
  document.addEventListener("dragover", function (e) {
    var t = e.target;
    if (t.classList && t.classList.contains("disc-item")) { e.preventDefault(); clearOver(); t.classList.add("is-over"); }
  }, false);
  document.addEventListener("drop", function (e) {
    var t = e.target;
    if (t.classList && t.classList.contains("disc-item") && dragSrc) {
      e.preventDefault(); e.stopPropagation();
      sort Insert(dragSrc, t, e.clientY);
      clearOver();
    }
  }, false);
  var touchItem = null, touchMoved = false;
  document.addEventListener("touchmove", function (e) {
    var t = e.touches[0]; if (!t) return;
    var tgt = document.elementFromPointer(t.clientX, t.clientY);
    var li = tgt && tgt.closest ? tgt.closest(".disc-item") : null;
    if (!touchItem) { if (li && !touchMoved) { touchItem = li; touchMoved = true; } }
    else if (li && li !== touchItem) { sortInsert(touchItem, li, t.clientY); touchItem = li; }
    try { e.preventDefault(); } catch (x) {}
  }, { passive: false });
  document.addEventListener("touchstart", function () { touchItem = null; touchMoved = false; }, false);

  function collect() {
    var arr = [];
    document.querySelectorAll(".disc-list").forEach(function (ul) {
      var order = Array.prototype.slice.call(ul.children).map(function (li) { return li.getAttribute("data-type"); });
      arr.push(order);
    });
    return arr;
  }
  function score() {
    var arr = collect(); var maj = []; var min = [];
    arr.forEach(function (ls) { if (ls[0]) { maj.push(ls[0]); } if (ls[3]) { min.push(ls[3]); } });
    function cnt(a, t) { return a.filter(function (x) { return x === t; }).length; }
    return { d: cnt(maj, "d") - cnt(min, "d"), i: cnt(maj, "i") - cnt(min, "i"),
             s: cnt(maj, "s") - cnt(min, "s"), c: cnt(maj, "c") - cnt(min, "c") };
  }
  function topType(s) {
    var a = ["d", "i", "s", "c"].map(function (t) { return [t, s[t]]; });
    a.sort(function (x, y) { return y[1] - x[1]; });
    return a[0][0];
  }
  function rank(v) {
    var s = score(); var b = Math.min(100, Math.abs(v) / 24 * 100) / 2;
    var bar = byId("__TYPE__");
    if (v >= 0) { bar.style.marginLeft = "50%"; bar.style.width = b + "%"; bar.style.transform = "none"; }
    else { bar.style.marginLeft = (50 - b) + "%"; bar.style.width = b + "%"; }
    byId("__TYPE__").textContent = (v > 0 ? "+" : "") + v;
  }
  function showResults() {
    var s = score();
    ["d", "i", "s", "c"].forEach(function (t) { rankByType(s, t); });
    var tt = topType(s); var r = RES_MAP[tt];
    if (!r) { r = RES_MAP["d"]; }
    byId("name0").textContent = NAME_MAP[tt];
    byId("discSummary").innerHTML =
      "<h3>" + es(r[0]) + "</h3>" +
      "<dl><dt>Кратко</dt><dd>" + es(r[1]) + "</dd>" +
      "<dt>Сильные стороны</dt><dd>" + es(r[2]) + "</dd>" +
      "<dt>Слабые стороны</dt><dd>" + es(r[3]) + "</dd>" +
      "<dt>Рекомендация</dt><dd>" + es(r[4]) + "</dd></dl>" +
      "<p>Баллы всех типов: D:" + s.d + ", I:" + s.i + ", S:" + s.s + ", C:" + s.c + ".</p>";
    byId("inputLink").value = (location.origin || "") + location.pathname + "?type=" + tt.toUpperCase();
  }
  function rankByType(s, t) {
    var v = s[t];
    var b = byId("b" + t); var width = Math.min(100, Math.abs(v) / 24 * 100) / 2;
    document.getElementById("v" + t).textContent = (v > 0 ? "+" : "") + v;
    if (v >= 0) { b.style.marginLeft = "50%"; b.style.width = width + "%"; b.style.transform = "none"; }
    else { b.style.marginLeft = (50 - width) + "%"; b.style.width = width + "%"; }
  }
  var ov = el("#discOverlay");
  function close() { ov.classList.remove("is-open"); ov.setAttribute("aria-hidden", "true"); document.body.classList.remove("no-scroll"); }
  function showStepUI(showNext) {
    byId("discBack").disabled = cur === 0;
    var next = byId("discNext"), finish = byId("discFinish");
    next.style.display = showNext ? "" : "none";
    finish.style.display = showNext ? "none" : "";
  }
  function render() {
    document.querySelectorAll(".disc-tab").forEach(function (t) {
      var i = Number(t.dataset.step); var on = i === cur;
      t.classList.toggle("is-active", on);
      t.setAttribute("aria-selected", on ? "true" : "false");
    });
    document.querySelectorAll(".disc-pane").forEach(function (p) { p.classList.toggle("is-active", Number(p.dataset.pane) === cur); });
    byId("discBar").style.width = ((cur + 1) / TOTAL * 100) + "%";
    byId("discLabel").textContent = STEP[cur] + " · вопрос " + (cur * 3) + 1 + " из " + (TOTAL * 3);
    showStepUI(cur < TOTAL - 1);
  }
  byId("discOpen").addEventListener("click", function () {
    ov.classList.add("is-open"); ov.setAttribute("aria-hidden", "false"); document.body.classList.add("no-scroll"); render();
  });
  document.getElementById("discClose").addEventListener("click", close);
