    var list=li.parentElement;
    var rect=li.getBoundingClientRect();
    var below = y > rect.top + rect.height/2;
    // move dragged before or after current li depending on pointer position relative to list
    var listTop = list.getBoundingClientRect().top;
    var idx = [];
    [].forEach.call(list.children, function(lii){ idx.push(lii); });
    // compute a target insertion index based on pointer
    var avg = rect.top + rect.height/2;
    var ref = below ? li.nextElementSibling : li;
