# -*- coding: utf-8 -*-
import json, os

HERE = "/home/dp/MyProjects/disc/test-assignment/reference/questions.json"
OUT = "/home/dp/MyProjects/disc/index.html"

RAW = json.load(open(HERE, encoding="utf-8"))
Q = RAW["questions"]
assert len(Q) == 24, len(Q)
QJSON = json.dumps(Q, ensure_ascii=False, separators=(",", ":"))

NAMES = {"d":"D · Доминирующий","i":"I · Влияющий","s":"S · Поддерживающий","c":"C · Сознательный"}
TITLE = {"D":"Доминирующий","I":"Влияющий","S":"Поддерживающий","C":"Сознательный"}
BAR = {"d":"#ef4444","i":"#f59e0b","s":"#22c55e","c":"#3b82f6"}
BRIEF = {
 "d":["D · Доминирующий","Ты ставишь цели и добиваешься их — ты «движок» команды. Принимаешь быструые решения, берёшь ответственность за них на себя, прямо говоришь и идёшь к результату.","Напористость, решительность, прямые вызовы","Нетерпение, напор на людей","Дай себе паузу перед важными решениями."],
 "i":["I · Влияющий","Ты — душа компании и вдохновитель. Находимый лёгкий контакт с людьми, заряжаешь позитивом, убеждаешь и мотивируете команду.","Обчельность, оптимизм, харизма, коммуникация","Рассеянность, поверхностность, сложности в рutine","Доверь рутину и документирование системе."],
 "s":["S · Поддерживающий","Ты надёжный, терпеливой и верный. Ценишь стабильность и искреннюю забат о людях, отлично слушаешь и умеешь поддерживать","Терпение, надёжность, стабильность","Нежелание перемен, сложности с решением","Попробуй иногда брать инициативу."],
 "c":["C · Сознательный","Ты внимательный к деталям и качеству. Ценишь стандарты, точность и правила; принимаешь решения на основе фактов и анализа","Стремление к качеству, системность, аргументированность","Перфекционизм, сложности с решением","Разумные дедлайны; «хорошо достаточно» для чёрновых"],
}
NAMES_J = json.dumps(NAMES)
TITLE_J = json.dumps(TITLE)
BAR_J = json.dumps(BAR)
BRIEF_J = json.dumps(BRIEF)

JS = r"""
;(function(){
  "use strict";
  var QUESTS = __QUESTS__;
  var NAMES = __NAMES__;
  var TITLE = __TITLE__;
  var BAR = __BAR__;
  var BRIEF = __BRIEF__;
  var TOTAL = QUESTS.length / 3; // 8
  var cur = 0;
  var dragged = null;

  var byId = function(id){ return document.getElementById(id); };
  var $ = function(s){ return document.querySelectorAll(s); };
  function es(s){ return String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;"); }

  function buildTabs(){
    var t = byId("tabs"); if(!t) return;
    t.innerHTML = "";
    for (var i=0;i<TOTAL;i++){
      var b=document.createElement("div");
      b.className="tab"+(i===0?" is-active":"");
      b.setAttribute("data-step",i); b.setAttribute("role","tab");
      b.setAttribute("aria-selected",i===0?"true":"false");
      b.setAttribute("aria-controls","pane"+i);
      b.textContent=""+(i+1);
      t.appendChild(b);
    }
  }
  function renderOne(q){
    var lis=q.items.map(function(it){
      return '<li class="item"><span class="item__text">'+es(it.text)+'</span>'
           +'<span class="tag t-'+it.type+'" data-type="'+it.type+'" aria-hidden="true">'+it.type.toUpperCase()+'</span></li>';
    }).join("");
    return '<ul class="list" id="list'+q.id+'">'+lis+'</ul>';
  }
  function buildPanes(){
    var c=byId("panes"); if(!c) return;
    const parts=[];
    for (var s=0;s<TOTAL;s++){
      var qs=QUESTS.filter(function(q){return q.step===s;});
      var cards=qs.map(function(q){
        return '<div class="card"><div class="card__title">Я Наиболее</div>'
              +renderOne(q)
              +'<div class="card__foot">Я Наименее</div></div>';
      }).join("");
      const active=s===0?" is-active":"";
      parts.push('<div class="pane'+active+'" data-pane="'+s+'" role="tabpanel" id="pane'+s+'"><div class="grid3">'+cards+'</div></div>');
    }
    c.innerHTML=parts.join("");
  }
  function clearOver(){
    [].forEach.call(document.querySelectorAll(".item.is-over"),function(x){x.classList.remove("is-over");});
  }
  function dropAt(item,y){
    var li=item.closest? item.closest(".item") : item;
    if(!li || !li.classList||li.classList.contains("item")||d===li) return;
    ul=li.parentElement; if(!ul)return;
    var rect=li.getBoundingClientRect();
    var ref = (y > rect.top+rect.height/2)? li.nextElementSibling:li;
    if (ref && ref.classList && ref.classList.contains("item")) ul.insertBefore(Drag,ref);
    else ul.appendChild(Drag);
  }
  var Drag=null;
  document.addEventListener("dragstart",function(e){ var t=e.target; if(t.classList&&t.classList.contains("item")){Drag=t;t.classList.add("is-dragging");e.dataTransfer.effectAllowed="move";}});
  document.addEventListener("dragend",function(){ if(Drag)Drag.classList.remove("is-dragging");Drag=null;clearOver();});
  document.addEventListener("dragover",function(e){ var t=e.target; if(t.classList&&t.classList.contains("item")){e.preventDefault();clearOver();t.classList.add("is-over");}});
  document.addEventListener("drop",function(e){ var t=e.target; if(t.classList&&t.classList.contains("item")){e.preventDefault();dropAt(t);clearOver();}});
  function collect(){
    var arr=[];
    [].forEach.call(document.querySelectorAll(".list"),function(ul){
      var order=[];
      [].forEach.call(ul.children,function(li){order.push(li.getAttribute("data-type"));});
      arr.push(order);
    });
    return arr;
  }
  function score(){
    var arr=collect(); var maj=[]; var min=[];
    arr.forEach(function(items){
      if(items.length>=1 && items[0]) maj.push(items[0]);
      if(items.length>=4 && items[3]) min.push(items[3]);
    });
    function count(a,t){return a.filter(function(x){return x===t;}).length;}
    return {d:count(maj,"d")-count(min,"d"),i:count(maj,"i")-count(min,"i"),s:count(maj,"s")-count(min,"s"),c:count(maj,"c")-count(min,"c")};
  }
  function rank(v){}
  function top(s){var b="d",v=-1e9;["d","i","s","c"].forEach(function(t){if(s[t]>v){v=s[t];b=t;}});return b;}
  function showResults(){
    var s=score();
    var board=byId("resultInfo").parentElement || byId("resultInfo");
    var html='';
    ["d","i","s","c"].forEach(function(t){
      var val=s[t];
      var pc=Math.min(100,Math.abs(val)/24*100)/2;
      var left=(val>=0)?"50%":(50-pc)+"%";
      var wid=pc+"%";
      html+='<div class="kpi"><div class="kpi__tag">'+TITLE[t.toUpperCase()]+'</div><div class="kpi__name" id="nm'+t.toUpperCase()+'">'+NAMES[t]+'</div>';
      html+='<div class="kpi__bar"><div class="kpi__barinner" style="background:'+BAR[t]+';margin-left:'+left+';width:'+wid+';"></div></div>';
      html+='<div class="kpi__val" id="val'+t.toUpperCase()+'">'+(val>0?'+':'')+val+'</div></div>';
    });
    var tt=top(s);
    var info=NAMES[tt];
    var b=BRIEF[tt];
    byId("resultInfo").innerHTML=html
      +'<h3>'+es(b[0])+'</h3><p>'+es(b[1])+'</p><p>'+es(b[2])+'</p><p>'+es(b[3])+'</p><p><b>Рекомендация:</b> '+es(b[4])+'</p>';
    byId("scoreSummary").textContent="D: "+s.d+", I: "+s.i+", S: "+s.s+", C: "+s.c+" (сумма = "+(s.d+s.i+s.s+s.c)+")";
    byId("shareLink").value=location.origin+location.pathname+"?top="+tt.toUpperCase();
    render();
  }
  function render(){
    [].forEach.call(document.querySelectorAll(".tab"),function(tb){
      var i=Number(tb.getAttribute("data-step"));var on=i===cur;
      tb.classList.toggle("is-active",on);
      tb.setAttribute("aria-selected",on?"true":"false");
    });
    [].forEach.call(document.querySelectorAll(".pane"),function(p){
      p.classList.toggle("is-active",Number(p.getAttribute("data-pane"))===cur);
    });
    var bar=byId("bar"); if(bar)bar.style.width=((cur+1)/TOTAL*100)+"%";
    var lbl=byId("progressLabel"); if(lbl)lbl.textContent="ШАГ "+(cur+1)+" из "+total+" · "+(cur*3+1)+" из 24";
    var sb=byId("stepBack"); if(sb)sb.disabled=cur===0;
    var nx=byId("stepNext"); var fx=byId("stepFinish");
    if(nx)nx.style.display=(cur>=TOTAL-1)?"none":"";
    if(fx)fx.style.display=(cur>=TOTAL-1)?"":"none";
  }
  function openTest(){
    var ov=byId("overlay"); if(ov){ov.classList.add("is-open");ov.setAttribute("aria-hidden","false");}
    document.body.classList.add("no-scroll");
  }
  function closeTest(){
    var ov=byId("overlay"); if(ov){ov.classList.remove("is-open");ov.setAttribute("aria-hidden","true");}
    document.body.classList.remove("no-scroll");
  }
  function runToEnd(){
    var btns=document.querySelectorAll(".footer__btn");
    [].forEach.call(btns,function(b){b.style.display="none";});
    showResults();
    closeTest();
  }
  // init
  buildTabs();
  buildPanes();
  render();
  function add(id,ev,fn){var el=byId(id); if(el) el.addEventListener(ev,fn,false); }
  add("startBtn","click",openTest);
  add("closeBtn","click",closeTest);
  add("stepBack","click",function(){if(cur>0){—cur--;render();}});
  add("stepNext","click",function(){if(cur<TOTAL-1){cur++;render();}});
  add("stepFinish","click",runToEnd);
  add("againBtn","click",function(){location.reload();});
  add("copyBtn","click",function(){var i=byId("shareLink"); if(i){i.select();try{document.execCommand("copy");}catch(e){}}byId("copyBtn").textContent="Скопировано";byId("copyBtn").classList.add("copied");setTimeout(function(){byId("copyBtn").textContent="Копировать ссылку";byId("copyBtn").classList.remove("copied");},1500);});
  document.addEventListener("keydown",function(e){if(e.key==="Escape"&&byId("overlay").classList.contains("is-open")) closeTest();});
  byId("againBtn");
})();
